<?php
namespace App\Http\Controllers;
use App\Models\Warehouse; use Illuminate\Http\Request; use Inertia\Inertia;
class WarehouseController extends Controller { public function index(){return Inertia::render('Warehouses/Index',['warehouses'=>Warehouse::withCount('stocks')->orderBy('name')->get()]);} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:150','code'=>'required|string|max:50|unique:warehouses,code','type'=>'required|string|max:30','address'=>'nullable|string|max:255','responsible'=>'nullable|string|max:150']); Warehouse::create($d+['active'=>true]); return back()->with('success','Gestiunea a fost creată.');} public function update(Request $r,Warehouse $warehouse){$d=$r->validate(['name'=>'required|string|max:150','code'=>'required|string|max:50|unique:warehouses,code,'.$warehouse->id,'type'=>'required|string|max:30','address'=>'nullable|string|max:255','responsible'=>'nullable|string|max:150','active'=>'boolean']);$warehouse->update($d);return back()->with('success','Gestiunea a fost actualizată.');} public function destroy(Warehouse $warehouse){if($warehouse->stocks()->exists()){return back()->withErrors(['warehouse'=>'Gestiunea nu poate fi ștearsă deoarece are stoc asociat. Dezactiveaz-o în schimb.']);}$warehouse->delete();return back()->with('success','Gestiunea a fost ștearsă.');} }
